<section class="section apply" id="apply" aria-labelledby="apply-title"><svg class="apply-bg" id="apply-bg" aria-hidden="true" width="100%" height="100%"><defs><pattern id="apply-pat" width="56" height="56" patternUnits="userSpaceOnUse"><rect x="18" y="18" width="20" height="20" transform="rotate(45 28 28)" fill="none" stroke="#FFFFFF" stroke-width="1.2"></rect></pattern><linearGradient id="apply-fade" x1="0" x2="1" y1="0" y2="0"><stop offset="0" stop-color="#fff" stop-opacity="1"></stop><stop offset=".55" stop-color="#fff" stop-opacity="0"></stop></linearGradient><mask id="apply-mask"><rect width="100%" height="100%" fill="url(#apply-fade)"></rect></mask></defs><rect width="100%" height="100%" fill="url(#apply-pat)" mask="url(#apply-mask)"></rect></svg><div class="wrap apply-grid"><div class="apply-side"><h1 class="h2" id="apply-title">Apply in four short steps</h1><p class="lead">Tell us who you are, what you&#x27;re building and where you&#x27;d like support. Applications go straight to the Abia Tech Hub team.</p><ul class="apply-points"><li><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><circle cx="12" cy="12" r="9"></circle><path d="M12 7v5l3 2"></path></svg>Takes about ten minutes</li><li><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 4h11l3 3v13H5z"></path><path d="M8 4v5h7V4M8 20v-6h8v6"></path></svg>Your draft saves on this device as you go</li><li><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.2" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="m5 12 4.5 4.5L19 7"></path></svg>Review everything before you send</li></ul></div><div class="form-card on-light" id="form-card"><div id="form-wrap"><ol class="stepper" id="stepper" aria-label="Application progress"></ol><div class="restore" id="restore" hidden=""><span>We restored the draft you started on this device.</span><button type="button" id="clear-draft">Start fresh</button></div><div class="form-head"><h3 id="step-title" tabindex="-1">About you</h3><span class="draft-note" id="draft-note" aria-live="polite"></span></div><p class="step-desc" id="step-desc">Start with your details so the team knows who you are and how to reach you.</p><form id="apply-form" data-step="1" noValidate=""><fieldset class="step-panel" id="step-1"><legend class="sr-only">About you</legend><div class="fields"><div class="field full"><label for="f-full_name">Full name</label><input class="input" id="f-full_name" type="text" autoComplete="name" maxLength="100" aria-describedby="err-full_name" name="full_name"/><p class="err" id="err-full_name" role="alert"></p></div><div class="field"><label for="f-email">Email</label><input class="input" id="f-email" type="email" autoComplete="email" inputMode="email" maxLength="120" aria-describedby="err-email" name="email"/><p class="err" id="err-email" role="alert"></p></div><div class="field"><label for="f-phone">Phone number</label><input class="input" id="f-phone" type="tel" autoComplete="tel" inputMode="tel" maxLength="20" aria-describedby="err-phone" name="phone"/><p class="err" id="err-phone" role="alert"></p></div><div class="field"><label for="f-institution">Institution</label><select class="input" id="f-institution" aria-describedby="hint-institution err-institution" name="institution"><option value="" selected disabled>Choose your institution</option>@foreach (array_merge(...array_values(\App\Http\Controllers\ApplyController::INSTITUTIONS)) as $institution)<option value="{{ $institution }}">{{ $institution }}</option>@endforeach</select><p class="hint" id="hint-institution">The Abia institution where you study</p><p class="err" id="err-institution" role="alert"></p></div><div class="field"><label for="f-course">Course or department</label><input class="input" id="f-course" type="text" maxLength="120" aria-describedby="err-course" name="course"/><p class="err" id="err-course" role="alert"></p></div><fieldset class="group field full" id="grp-year" aria-describedby="err-year"><legend class="group-label">Year of study</legend><div class="chips"><div class="chip"><input type="radio" id="yr-1" name="year" value="First year"/><label for="yr-1">First year</label></div><div class="chip"><input type="radio" id="yr-2" name="year" value="Second year"/><label for="yr-2">Second year</label></div><div class="chip"><input type="radio" id="yr-3" name="year" value="Third year"/><label for="yr-3">Third year</label></div><div class="chip"><input type="radio" id="yr-4" name="year" value="Fourth year"/><label for="yr-4">Fourth year</label></div><div class="chip"><input type="radio" id="yr-5" name="year" value="Fifth year or above"/><label for="yr-5">Fifth year or above</label></div><div class="chip"><input type="radio" id="yr-6" name="year" value="Postgraduate"/><label for="yr-6">Postgraduate</label></div></div><p class="err" id="err-year" role="alert"></p></fieldset></div></fieldset><fieldset class="step-panel" id="step-2" hidden=""><legend class="sr-only">Your startup</legend><div class="fields"><div class="field"><label for="f-startup_name">Startup name</label><input class="input" id="f-startup_name" type="text" maxLength="80" aria-describedby="err-startup_name" name="startup_name"/><p class="err" id="err-startup_name" role="alert"></p></div><div class="field"><label for="f-sector">Sector</label><select class="input" id="f-sector" name="sector" aria-describedby="err-sector"><option value="">Choose a sector</option><option>Agriculture and food</option><option>Education</option><option>Health</option><option>Finance and payments</option><option>Commerce and retail</option><option>Manufacturing and trade</option><option>Logistics and mobility</option><option>Fashion and creative</option><option>Energy and climate</option><option>Media and entertainment</option><option>Other</option></select><p class="err" id="err-sector" role="alert"></p></div><fieldset class="group field full" id="grp-stage" aria-describedby="err-stage"><legend class="group-label">How far along are you?</legend><div class="cards"><div class="card-opt"><input type="radio" id="st-1" name="stage" value="Just an idea"/><label for="st-1"><span class="dot"></span><span><strong>Just an idea</strong><span>I know the problem and have a solution in mind</span></span></label></div><div class="card-opt"><input type="radio" id="st-2" name="stage" value="Building a prototype"/><label for="st-2"><span class="dot"></span><span><strong>Building a prototype</strong><span>I&#x27;m making a first version</span></span></label></div><div class="card-opt"><input type="radio" id="st-3" name="stage" value="Early users or customers"/><label for="st-3"><span class="dot"></span><span><strong>Early users</strong><span>Some people are already using it</span></span></label></div><div class="card-opt"><input type="radio" id="st-4" name="stage" value="Making revenue"/><label for="st-4"><span class="dot"></span><span><strong>Making revenue</strong><span>Customers are paying for it</span></span></label></div></div><p class="err" id="err-stage" role="alert"></p></fieldset><div class="field full"><label for="f-problem">What problem are you solving, and for whom?</label><textarea class="input" id="f-problem" name="problem" maxLength="600" aria-describedby="err-problem cnt-problem"></textarea><p class="counter" id="cnt-problem">0 / 600</p><p class="err" id="err-problem" role="alert"></p></div><div class="field full"><label for="f-solution">What&#x27;s your solution?</label><textarea class="input" id="f-solution" name="solution" maxLength="600" aria-describedby="err-solution cnt-solution"></textarea><p class="counter" id="cnt-solution">0 / 600</p><p class="err" id="err-solution" role="alert"></p></div><fieldset class="group field" id="grp-team_size" aria-describedby="err-team_size"><legend class="group-label">Team size</legend><div class="chips"><div class="chip"><input type="radio" id="tm-1" name="team_size" value="Just me"/><label for="tm-1">Just me</label></div><div class="chip"><input type="radio" id="tm-2" name="team_size" value="2 people"/><label for="tm-2">2</label></div><div class="chip"><input type="radio" id="tm-3" name="team_size" value="3 to 4 people"/><label for="tm-3">3 to 4</label></div><div class="chip"><input type="radio" id="tm-4" name="team_size" value="5 or more"/><label for="tm-4">5+</label></div></div><p class="err" id="err-team_size" role="alert"></p></fieldset><div class="field"><label for="f-link">Website or social link <span class="opt">(optional)</span></label><input class="input" id="f-link" type="text" inputMode="url" maxLength="200" aria-describedby="err-link" name="link"/><p class="err" id="err-link" role="alert"></p></div></div></fieldset><fieldset class="step-panel" id="step-3" hidden=""><legend class="sr-only">Mentorship needs</legend><div class="fields"><fieldset class="group field full" id="grp-mentor_areas" aria-describedby="hint-areas err-mentor_areas"><legend class="group-label">Where would mentorship help most?</legend><p class="hint" id="hint-areas" style="margin-bottom:10px">Choose all that apply</p><div class="chips" id="area-chips"></div><p class="err" id="err-mentor_areas" role="alert"></p></fieldset><div class="field full"><label for="f-goal">What do you hope to achieve in the 6 weeks?</label><textarea class="input" id="f-goal" name="goal" maxLength="600" aria-describedby="err-goal cnt-goal"></textarea><p class="counter" id="cnt-goal">0 / 600</p><p class="err" id="err-goal" role="alert"></p></div><fieldset class="group field full" id="grp-commitment" aria-describedby="err-commitment"><legend class="group-label">Can you take part for all 6 weeks?</legend><div class="cards"><div class="card-opt"><input type="radio" id="cm-1" name="commitment" value="Yes, for all 6 weeks"/><label for="cm-1"><span class="dot"></span><span><strong>Yes, all 6 weeks</strong><span>I can commit for the whole programme</span></span></label></div><div class="card-opt"><input type="radio" id="cm-2" name="commitment" value="Would need some flexibility"/><label for="cm-2"><span class="dot"></span><span><strong>I&#x27;d need some flexibility</strong><span>For example around exams or lectures</span></span></label></div></div><p class="err" id="err-commitment" role="alert"></p></fieldset><div class="field full"><label for="f-heard">How did you hear about the programme? <span class="opt">(optional)</span></label><select class="input" id="f-heard" name="heard"><option value="">Choose one</option><option>A friend or classmate</option><option>My institution</option><option>Social media</option><option>An Abia Tech Hub event</option><option>Other</option></select></div><div class="field full"><label class="consent" for="f-consent"><input type="checkbox" id="f-consent" aria-describedby="err-consent" name="consent" value="yes"/><span>I confirm the details in this application are accurate, and I&#x27;m happy for Abia Tech Hub to contact me about it.</span></label><p class="err" id="err-consent" role="alert"></p></div></div></fieldset><div class="step-panel" id="step-4" hidden=""><div class="review" id="review"></div></div><p class="form-status" id="form-status" role="alert" hidden=""></p><div class="form-nav"><button class="btn btn-quiet" type="button" id="back-btn" hidden=""><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true" style="transform:none"><path d="M19 12H5M11 6l-6 6 6 6"></path></svg>Back</button><span class="spacer"></span><button class="btn btn-forest" type="submit" id="next-btn"><span id="next-label">Continue</span><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6"></path></svg></button></div></form></div><div class="success" id="apply-success" hidden="" tabindex="-1"><svg class="success-mark" viewBox="0 0 100 100" aria-hidden="true"><rect x="18" y="18" width="64" height="64" rx="10" transform="rotate(45 50 50)" fill="#0A0E27"></rect><path d="M34 51 l11 11 l22 -24" fill="none" stroke="#FFFFFF" stroke-width="6" stroke-linecap="round" stroke-linejoin="round"></path></svg><h3>Application sent</h3><p id="success-text">Your application has reached the Abia Tech Hub team.</p><a class="btn btn-forest" href="/">Back to the home page</a></div></div></div></section>
